try:
    import tomllib
except ImportError:
    tomllib = None

def _from_pyproject(root: Path) -> list[str]:
    """``[project].dependencies`` + ``[tool.poetry.dependencies]`` keys (no 'python')."""
    path = root / "pyproject.toml"
    if not path.is_file():
        return []

    if tomllib is not None:
        try:
            with open(path, "rb") as f:
                data = tomllib.load(f)
        except Exception:
            return []
    else:
        # Fallback for Python < 3.11
        import re
        try:
            content = path.read_text(encoding="utf-8")
        except Exception:
            return []

        deps = []
        in_project = False
        in_poetry = False

        for line in content.splitlines():
            line = line.strip()
            if not line or line.startswith("#"):
                continue

            if line.startswith("["):
                in_project = line.replace(" ", "") == "[project]"
                in_poetry = line.replace(" ", "") == "[tool.poetry.dependencies]"
                continue

            if in_project and line.startswith("dependencies"):
                match = re.search(r'dependencies\s*=\s*\[(.*?)\]', line)
                if match:
                    for item in match.group(1).split(","):
                        item = item.strip().strip("'\"")
                        if item:
                            deps.append(item)
            elif in_poetry and "=" in line:
                dep_name = line.split("=")[0].strip().strip("'\"")
                if dep_name and dep_name != "python":
                    deps.append(dep_name)

        return deps

    deps = []

    if "project" in data and isinstance(data["project"], dict):
        proj_deps = data["project"].get("dependencies")
        if isinstance(proj_deps, list):
            deps.extend(str(d) for d in proj_deps)

    if "tool" in data and isinstance(data["tool"], dict):
        poetry = data["tool"].get("poetry")
        if isinstance(poetry, dict):
            poetry_deps = poetry.get("dependencies")
            if isinstance(poetry_deps, dict):
                for dep in poetry_deps:
                    if str(dep) != "python":
                        deps.append(str(dep))

    return deps

