        val = parser.get("options", "install_requires")
        return [line.strip() for line in val.splitlines() if line.strip()]

    return []

import ast
from pathlib import Path

def _from_setup_py(root: Path) -> list[str]:
    """Best-effort: a literal ``install_requires=[...]`` string list (AST)."""
    setup_py = root / "setup.py"
    if not setup_py.is_file():
        return []

    try:
        content = setup_py.read_text(encoding="utf-8")
        tree = ast.parse(content)
    except Exception:
        return []

    for node in ast.walk(tree):
        if isinstance(node, ast.keyword) and node.arg == "install_requires":
            if isinstance(node.value, ast.List):
                reqs = []
                for elt in node.value.elts:
                    if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                        reqs.append(elt.value)
                    elif type(elt).__name__ == "Str":
                        reqs.append(getattr(elt, "s"))
                return reqs
        elif isinstance(node, ast.Assign):
            for target in node.targets:
                if isinstance(target, ast.Name) and target.id == "install_requires":
                    if isinstance(node.value, ast.List):
                        reqs = []
                        for elt in node.value.elts:
                            if isinstance(elt, ast.Constant) and isinstance(elt.value, str):
                                reqs.append(elt.value)
                            elif type(elt).__name__ == "Str":
                                reqs.append(getattr(elt, "s"))
                        return reqs
    return []

