def _project_py_files(root: Path) -> list[Path]:
    """Rel paths of the project's own ``.py`` files (skipping vendor/build dirs)."""
    out = []
    skip_dirs = {"vendor", "build", "dist", "venv", "env", "__pycache__", "node_modules"}
    for path in root.rglob("*.py"):
        rel = path.relative_to(root)
        if any(part.startswith(".") or part in skip_dirs for part in rel.parts[:-1]):
            continue
        out.append(rel)
    return out

