def _intra_project_names(root: Path, py_files: list[Path]) -> set[str]:
    """Top-level package/module names owned by the project (+ ``source_root.name``)."""
    names = {root.name}
    for p in py_files:
        try:
            rel = p.relative_to(root) if p.is_absolute() else p
        except ValueError:
            rel = p

        if not rel.parts:
            continue

        if len(rel.parts) == 1:
            names.add(rel.stem)
        else:
            names.add(rel.parts[0])

    return names

